-- =====================================================================
-- Intelligent Healthcare & Patient Diagnostic System   (MySQL 8.0.19+)
-- Modules: 1 Patient & History | 2 Doctors | 3 Appointments
--          4 AI Diagnostics    | 5 Prescriptions & Labs
-- Data:   AI knowledge base built from the Kaggle "Disease Symptom Prediction"
--         dataset (4,920 records, 41 diseases, 131 symptoms) -> see kaggle_import.py
-- Run:  mysql -u root -p < healthcare_mysql.sql
-- =====================================================================

SET NAMES utf8mb4;          -- read this file as UTF-8 on every OS
DROP DATABASE IF EXISTS healthcare;
CREATE DATABASE healthcare CHARACTER SET utf8mb4;
USE healthcare;
SET time_zone = '+05:30';   -- sample data below is written in Indian Standard Time

-- =====================================================================
-- MODULE 1: PATIENT & MEDICAL HISTORY
-- =====================================================================
CREATE TABLE patients (
    patient_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    first_name   VARCHAR(60)  NOT NULL,
    last_name    VARCHAR(60)  NOT NULL,
    date_of_birth DATE        NOT NULL,
    gender       VARCHAR(10)  NOT NULL,
    blood_group  VARCHAR(3),
    phone        VARCHAR(20)  NOT NULL UNIQUE,
    email        VARCHAR(120) UNIQUE,
    address      TEXT,
    city         VARCHAR(80),
    insurance_provider  VARCHAR(100),
    insurance_policy_no VARCHAR(50),
    registered_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    is_active    BOOLEAN      NOT NULL DEFAULT TRUE,
    CHECK (gender IN ('Male','Female','Other')),
    CHECK (blood_group IN ('A+','A-','B+','B-','AB+','AB-','O+','O-'))
);

CREATE TABLE patient_emergency_contacts (
    contact_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    patient_id   BIGINT       NOT NULL,
    name         VARCHAR(100) NOT NULL,
    relationship VARCHAR(50)  NOT NULL,
    phone        VARCHAR(20)  NOT NULL,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id) ON DELETE CASCADE
);

CREATE TABLE medical_history (
    history_id     BIGINT AUTO_INCREMENT PRIMARY KEY,
    patient_id     BIGINT       NOT NULL,
    condition_name VARCHAR(150) NOT NULL,
    icd10_code     VARCHAR(10),
    category       VARCHAR(20)  NOT NULL DEFAULT 'Chronic',
    diagnosed_on   DATE,
    status         VARCHAR(15)  NOT NULL DEFAULT 'Active',
    notes          TEXT,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id) ON DELETE CASCADE,
    CHECK (category IN ('Chronic','Past Illness','Surgery','Family History','Immunization')),
    CHECK (status IN ('Active','Resolved','Managed'))
);

CREATE TABLE allergies (
    allergy_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT       NOT NULL,
    allergen   VARCHAR(100) NOT NULL,
    reaction   VARCHAR(150),
    severity   VARCHAR(10)  NOT NULL,
    UNIQUE (patient_id, allergen),
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id) ON DELETE CASCADE,
    CHECK (severity IN ('Mild','Moderate','Severe'))
);

CREATE TABLE patient_vitals (
    vital_id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    patient_id       BIGINT    NOT NULL,
    recorded_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    temperature_c    DECIMAL(4,1),
    heart_rate_bpm   SMALLINT,
    systolic_bp      SMALLINT,
    diastolic_bp     SMALLINT,
    respiratory_rate SMALLINT,
    spo2_percent     DECIMAL(4,1),
    blood_glucose_mgdl DECIMAL(5,1),
    weight_kg        DECIMAL(5,1),
    height_cm        DECIMAL(5,1),
    recorded_by      VARCHAR(100),
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id) ON DELETE CASCADE,
    CHECK (temperature_c BETWEEN 30 AND 45),
    CHECK (heart_rate_bpm BETWEEN 20 AND 250),
    CHECK (systolic_bp BETWEEN 40 AND 300),
    CHECK (diastolic_bp BETWEEN 20 AND 200),
    CHECK (respiratory_rate BETWEEN 4 AND 80),
    CHECK (spo2_percent BETWEEN 50 AND 100),
    CHECK (weight_kg > 0),
    CHECK (height_cm > 0)
);

-- =====================================================================
-- MODULE 2: DOCTOR & SPECIALIZATION DIRECTORY
-- =====================================================================
CREATE TABLE specializations (
    specialization_id INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(100) NOT NULL UNIQUE,
    description TEXT
);

CREATE TABLE doctors (
    doctor_id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    first_name       VARCHAR(60)  NOT NULL,
    last_name        VARCHAR(60)  NOT NULL,
    gender           VARCHAR(10)  NOT NULL DEFAULT 'Other',
    license_number   VARCHAR(50)  NOT NULL UNIQUE,
    phone            VARCHAR(20)  NOT NULL,
    email            VARCHAR(120) NOT NULL UNIQUE,
    qualification    VARCHAR(150),
    experience_years SMALLINT,
    consultation_fee DECIMAL(10,2) NOT NULL DEFAULT 0,
    languages        VARCHAR(120),
    room_no          VARCHAR(20),
    bio              TEXT,
    joined_on        DATE,
    is_active        BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (gender IN ('Male','Female','Other')),
    CHECK (experience_years >= 0),
    CHECK (consultation_fee >= 0)
);

CREATE TABLE doctor_specializations (
    doctor_id         BIGINT NOT NULL,
    specialization_id INT    NOT NULL,
    is_primary        BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (doctor_id, specialization_id),
    FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id) ON DELETE CASCADE,
    FOREIGN KEY (specialization_id) REFERENCES specializations(specialization_id)
);

-- Weekly availability (0 = Sunday ... 6 = Saturday)
CREATE TABLE doctor_schedules (
    schedule_id  BIGINT AUTO_INCREMENT PRIMARY KEY,
    doctor_id    BIGINT   NOT NULL,
    day_of_week  SMALLINT NOT NULL,
    start_time   TIME     NOT NULL,
    end_time     TIME     NOT NULL,
    slot_minutes SMALLINT NOT NULL DEFAULT 30,
    UNIQUE (doctor_id, day_of_week, start_time),
    FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id) ON DELETE CASCADE,
    CHECK (day_of_week BETWEEN 0 AND 6),
    CHECK (end_time > start_time),
    CHECK (slot_minutes > 0)
);

CREATE TABLE doctor_leaves (
    leave_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    doctor_id  BIGINT NOT NULL,
    leave_from DATE   NOT NULL,
    leave_to   DATE   NOT NULL,
    reason     VARCHAR(200),
    FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id) ON DELETE CASCADE,
    CHECK (leave_to >= leave_from)
);

-- =====================================================================
-- MODULE 3: APPOINTMENTS & CONSULTATION LOGS
-- =====================================================================
CREATE TABLE appointments (
    appointment_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    patient_id       BIGINT    NOT NULL,
    doctor_id        BIGINT    NOT NULL,
    start_time       TIMESTAMP NOT NULL,
    end_time         TIMESTAMP NOT NULL,
    appointment_type VARCHAR(15) NOT NULL DEFAULT 'In-Person',
    status           VARCHAR(15) NOT NULL DEFAULT 'Scheduled',
    reason           TEXT,
    created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id),
    FOREIGN KEY (doctor_id)  REFERENCES doctors(doctor_id),
    CHECK (end_time > start_time),
    CHECK (appointment_type IN ('In-Person','Video','Phone')),
    CHECK (status IN ('Scheduled','Completed','Cancelled','No-Show'))
);

CREATE TABLE consultations (
    consultation_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    appointment_id    BIGINT NOT NULL UNIQUE,
    chief_complaint   TEXT   NOT NULL,
    examination_notes TEXT,
    diagnosis         TEXT,
    icd10_code        VARCHAR(10),
    treatment_plan    TEXT,
    follow_up_date    DATE,
    vital_id          BIGINT,
    ai_check_id       BIGINT,
    logged_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (appointment_id) REFERENCES appointments(appointment_id),
    FOREIGN KEY (vital_id)       REFERENCES patient_vitals(vital_id)
);

-- =====================================================================
-- MODULE 4: AI DIAGNOSTIC & SYMPTOM LOGS
-- =====================================================================
CREATE TABLE symptoms (
    symptom_id      INT AUTO_INCREMENT PRIMARY KEY,
    name            VARCHAR(100) NOT NULL UNIQUE,
    kaggle_key      VARCHAR(80)  UNIQUE,          -- original column value in the Kaggle CSV
    body_system     VARCHAR(50),
    severity_weight SMALLINT,                     -- Kaggle Symptom-severity.csv (1 = mild, 7 = severe)
    description     TEXT,
    CHECK (severity_weight BETWEEN 1 AND 7)
);

CREATE TABLE diseases (
    disease_id     INT AUTO_INCREMENT PRIMARY KEY,
    name           VARCHAR(150) NOT NULL UNIQUE,
    icd10_code     VARCHAR(10),
    severity_level SMALLINT NOT NULL DEFAULT 1,
    recommended_specialization_id INT,
    description    TEXT,
    FOREIGN KEY (recommended_specialization_id) REFERENCES specializations(specialization_id),
    CHECK (severity_level BETWEEN 1 AND 5)
);

-- Kaggle symptom_precaution.csv: what the patient can do while waiting for care
CREATE TABLE disease_precautions (
    disease_id INT      NOT NULL,
    step_no    SMALLINT NOT NULL,
    precaution VARCHAR(200) NOT NULL,
    PRIMARY KEY (disease_id, step_no),
    FOREIGN KEY (disease_id) REFERENCES diseases(disease_id) ON DELETE CASCADE
);

-- Kaggle dataset.csv: the raw patient records the knowledge base is learned from
CREATE TABLE kaggle_cases (
    case_id    INT PRIMARY KEY,
    disease_id INT NOT NULL,
    FOREIGN KEY (disease_id) REFERENCES diseases(disease_id) ON DELETE CASCADE
);

CREATE TABLE kaggle_case_symptoms (
    case_id    INT NOT NULL,
    symptom_id INT NOT NULL,
    PRIMARY KEY (case_id, symptom_id),
    FOREIGN KEY (case_id)    REFERENCES kaggle_cases(case_id) ON DELETE CASCADE,
    FOREIGN KEY (symptom_id) REFERENCES symptoms(symptom_id)
);

-- Knowledge base: how strongly a symptom indicates a disease (0..1), derived from kaggle_cases
CREATE TABLE disease_symptoms (
    disease_id INT NOT NULL,
    symptom_id INT NOT NULL,
    weight     DECIMAL(3,2) NOT NULL,
    PRIMARY KEY (disease_id, symptom_id),
    FOREIGN KEY (disease_id) REFERENCES diseases(disease_id) ON DELETE CASCADE,
    FOREIGN KEY (symptom_id) REFERENCES symptoms(symptom_id) ON DELETE CASCADE,
    CHECK (weight BETWEEN 0 AND 1)
);

CREATE TABLE ai_models (
    model_id    INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    version     VARCHAR(30)  NOT NULL,
    deployed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    UNIQUE (name, version)
);

-- How well each model version matched the Kaggle records (filled by kaggle_import.py)
CREATE TABLE model_evaluations (
    eval_id       INT AUTO_INCREMENT PRIMARY KEY,
    model_id      INT          NOT NULL,
    dataset       VARCHAR(120) NOT NULL,
    method        VARCHAR(200) NOT NULL,
    records       INT          NOT NULL,
    top1_accuracy DECIMAL(5,4) NOT NULL,
    top3_accuracy DECIMAL(5,4) NOT NULL,
    evaluated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (model_id) REFERENCES ai_models(model_id) ON DELETE CASCADE,
    CHECK (top1_accuracy BETWEEN 0 AND 1),
    CHECK (top3_accuracy BETWEEN 0 AND 1)
);

CREATE TABLE symptom_checks (
    check_id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    patient_id      BIGINT NOT NULL,
    model_id        INT,
    free_text_input TEXT,
    vital_id        BIGINT,
    checked_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id) ON DELETE CASCADE,
    FOREIGN KEY (model_id)   REFERENCES ai_models(model_id),
    FOREIGN KEY (vital_id)   REFERENCES patient_vitals(vital_id)
);

ALTER TABLE consultations
    ADD CONSTRAINT fk_consult_ai_check FOREIGN KEY (ai_check_id) REFERENCES symptom_checks(check_id);

CREATE TABLE symptom_check_items (
    check_id      BIGINT NOT NULL,
    symptom_id    INT    NOT NULL,
    severity      SMALLINT NOT NULL DEFAULT 1,
    duration_days SMALLINT,
    PRIMARY KEY (check_id, symptom_id),
    FOREIGN KEY (check_id)   REFERENCES symptom_checks(check_id) ON DELETE CASCADE,
    FOREIGN KEY (symptom_id) REFERENCES symptoms(symptom_id),
    CHECK (severity BETWEEN 1 AND 5),
    CHECK (duration_days >= 0)
);

-- NOTE: "rank" is a reserved word in MySQL 8, so the column is prediction_rank
CREATE TABLE ai_predictions (
    prediction_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    check_id        BIGINT NOT NULL,
    disease_id      INT    NOT NULL,
    confidence      DECIMAL(5,4) NOT NULL,
    prediction_rank SMALLINT NOT NULL,
    urgency         VARCHAR(10) NOT NULL DEFAULT 'Routine',
    UNIQUE (check_id, disease_id),
    UNIQUE (check_id, prediction_rank),
    FOREIGN KEY (check_id)   REFERENCES symptom_checks(check_id) ON DELETE CASCADE,
    FOREIGN KEY (disease_id) REFERENCES diseases(disease_id),
    CHECK (confidence BETWEEN 0 AND 1),
    CHECK (prediction_rank >= 1),
    CHECK (urgency IN ('Routine','Soon','Urgent','Emergency'))
);

CREATE TABLE ai_feedback (
    feedback_id      BIGINT AUTO_INCREMENT PRIMARY KEY,
    prediction_id    BIGINT  NOT NULL,
    doctor_id        BIGINT  NOT NULL,
    was_correct      BOOLEAN NOT NULL,
    final_disease_id INT,
    comments         TEXT,
    created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (prediction_id)    REFERENCES ai_predictions(prediction_id) ON DELETE CASCADE,
    FOREIGN KEY (doctor_id)        REFERENCES doctors(doctor_id),
    FOREIGN KEY (final_disease_id) REFERENCES diseases(disease_id)
);

-- =====================================================================
-- MODULE 5: PRESCRIPTIONS & LAB REPORTS
-- =====================================================================
CREATE TABLE medications (
    medication_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    generic_name  VARCHAR(120) NOT NULL,
    brand_name    VARCHAR(120),
    form          VARCHAR(30),
    strength      VARCHAR(30),
    UNIQUE (generic_name, brand_name, strength),
    CHECK (form IN ('Tablet','Capsule','Syrup','Injection','Ointment','Drops','Inhaler'))
);

CREATE TABLE prescriptions (
    prescription_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    consultation_id BIGINT NOT NULL,
    issued_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    valid_until     DATE,
    instructions    TEXT,
    FOREIGN KEY (consultation_id) REFERENCES consultations(consultation_id) ON DELETE CASCADE
);

CREATE TABLE prescription_items (
    item_id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    prescription_id BIGINT NOT NULL,
    medication_id   BIGINT NOT NULL,
    dosage          VARCHAR(50) NOT NULL,
    frequency       VARCHAR(50) NOT NULL,
    duration_days   SMALLINT    NOT NULL,
    route           VARCHAR(20) DEFAULT 'Oral',
    notes           TEXT,
    FOREIGN KEY (prescription_id) REFERENCES prescriptions(prescription_id) ON DELETE CASCADE,
    FOREIGN KEY (medication_id)   REFERENCES medications(medication_id),
    CHECK (duration_days > 0)
);

CREATE TABLE lab_tests (
    test_id        INT AUTO_INCREMENT PRIMARY KEY,
    test_name      VARCHAR(120) NOT NULL UNIQUE,
    category       VARCHAR(50),
    unit           VARCHAR(20),
    ref_range_low  DECIMAL(10,2),
    ref_range_high DECIMAL(10,2)
);

CREATE TABLE lab_orders (
    order_id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    consultation_id BIGINT NOT NULL,
    ordered_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status          VARCHAR(20) NOT NULL DEFAULT 'Ordered',
    priority        VARCHAR(10) NOT NULL DEFAULT 'Routine',
    FOREIGN KEY (consultation_id) REFERENCES consultations(consultation_id) ON DELETE CASCADE,
    CHECK (status IN ('Ordered','Sample Collected','Completed','Cancelled')),
    CHECK (priority IN ('Routine','Urgent','STAT'))
);

CREATE TABLE lab_results (
    result_id    BIGINT AUTO_INCREMENT PRIMARY KEY,
    order_id     BIGINT NOT NULL,
    test_id      INT    NOT NULL,
    result_value DECIMAL(12,3) NOT NULL,
    flag         VARCHAR(10),
    reported_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    remarks      TEXT,
    UNIQUE (order_id, test_id),
    FOREIGN KEY (order_id) REFERENCES lab_orders(order_id) ON DELETE CASCADE,
    FOREIGN KEY (test_id)  REFERENCES lab_tests(test_id),
    CHECK (flag IN ('Low','Normal','High','Critical'))
);

-- =====================================================================
-- TRIGGERS  (MySQL has no EXCLUDE constraint, so triggers enforce these)
-- =====================================================================
DELIMITER $$

-- A doctor cannot have two overlapping active appointments
CREATE TRIGGER trg_appt_no_overlap_ins BEFORE INSERT ON appointments
FOR EACH ROW
BEGIN
    IF NEW.status IN ('Scheduled','Completed') AND EXISTS (
        SELECT 1 FROM appointments a
        WHERE a.doctor_id = NEW.doctor_id AND a.status IN ('Scheduled','Completed')
          AND a.start_time < NEW.end_time AND NEW.start_time < a.end_time) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'That doctor already has an appointment in this slot';
    END IF;
END$$

CREATE TRIGGER trg_appt_no_overlap_upd BEFORE UPDATE ON appointments
FOR EACH ROW
BEGIN
    IF NEW.status IN ('Scheduled','Completed') AND EXISTS (
        SELECT 1 FROM appointments a
        WHERE a.doctor_id = NEW.doctor_id AND a.status IN ('Scheduled','Completed')
          AND a.appointment_id <> NEW.appointment_id
          AND a.start_time < NEW.end_time AND NEW.start_time < a.end_time) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'That doctor already has an appointment in this slot';
    END IF;
END$$

-- Date of birth cannot be in the future (CHECK cannot use CURRENT_DATE in MySQL)
CREATE TRIGGER trg_patient_dob BEFORE INSERT ON patients
FOR EACH ROW
BEGIN
    IF NEW.date_of_birth > CURRENT_DATE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Date of birth cannot be in the future';
    END IF;
END$$

-- Auto-flag lab results against the reference range
CREATE TRIGGER trg_lab_flag BEFORE INSERT ON lab_results
FOR EACH ROW
BEGIN
    DECLARE lo DECIMAL(10,2);
    DECLARE hi DECIMAL(10,2);
    IF NEW.flag IS NULL THEN
        SELECT ref_range_low, ref_range_high INTO lo, hi FROM lab_tests WHERE test_id = NEW.test_id;
        SET NEW.flag = CASE
            WHEN lo IS NOT NULL AND NEW.result_value < lo THEN 'Low'
            WHEN hi IS NOT NULL AND NEW.result_value > hi THEN 'High'
            ELSE 'Normal' END;
    END IF;
END$$

-- =====================================================================
-- SYMPTOM MATCHING PROCEDURE:  CALL match_diseases(check_id, 5);
--   score = disease coverage x patient coverage
--   disease coverage = sum(weight * severity) of matched symptoms / sum(weight * 5) of all the disease's symptoms
--   patient coverage = severity of the reported symptoms this disease explains / severity of all reported symptoms
--   (patient coverage stops diseases with only 2-3 known symptoms winning on one match;
--    on the Kaggle records it lifts top-1 accuracy from 85.8% to 96.4%)
-- =====================================================================
CREATE PROCEDURE match_diseases(IN p_check_id BIGINT, IN p_top INT)
BEGIN
    SELECT d.disease_id, d.name AS disease_name,
           ROUND(SUM(ds.weight * sci.severity)
                 / (SELECT SUM(w.weight * 5) FROM disease_symptoms w WHERE w.disease_id = d.disease_id)
                 * SUM(sci.severity)
                 / (SELECT SUM(a.severity) FROM symptom_check_items a WHERE a.check_id = p_check_id), 4) AS match_score,
           COUNT(*) AS matched_symptoms
    FROM symptom_check_items sci
    JOIN disease_symptoms ds ON ds.symptom_id = sci.symptom_id
    JOIN diseases d          ON d.disease_id  = ds.disease_id
    WHERE sci.check_id = p_check_id
    GROUP BY d.disease_id, d.name
    ORDER BY match_score DESC
    LIMIT p_top;
END$$

DELIMITER ;

-- =====================================================================
-- INDEXES
-- =====================================================================
CREATE INDEX idx_vitals_patient_time ON patient_vitals (patient_id, recorded_at);
CREATE INDEX idx_history_patient     ON medical_history (patient_id);
CREATE INDEX idx_appt_patient        ON appointments (patient_id, start_time);
CREATE INDEX idx_appt_doctor_time    ON appointments (doctor_id, start_time, end_time);
CREATE INDEX idx_symcheck_patient    ON symptom_checks (patient_id, checked_at);
CREATE INDEX idx_dissym_symptom      ON disease_symptoms (symptom_id);
CREATE INDEX idx_kcs_symptom         ON kaggle_case_symptoms (symptom_id);

-- =====================================================================
-- VIEWS
-- =====================================================================
CREATE VIEW v_latest_vitals AS
SELECT x.* FROM (
    SELECT v.*, ROW_NUMBER() OVER (PARTITION BY patient_id ORDER BY recorded_at DESC, vital_id DESC) AS rn
    FROM patient_vitals v) x
WHERE x.rn = 1;

CREATE VIEW v_doctor_directory AS
SELECT d.doctor_id,
       CONCAT(d.first_name, ' ', d.last_name) AS doctor_name,
       GROUP_CONCAT(s.name ORDER BY ds.is_primary DESC, s.name SEPARATOR ', ') AS specializations,
       d.gender, d.languages, d.room_no, d.experience_years, d.consultation_fee
FROM doctors d
JOIN doctor_specializations ds ON ds.doctor_id = d.doctor_id
JOIN specializations s         ON s.specialization_id = ds.specialization_id
WHERE d.is_active
GROUP BY d.doctor_id;

-- How busy each doctor is (completed visits, upcoming bookings, distinct patients)
CREATE VIEW v_doctor_workload AS
SELECT d.doctor_id, CONCAT('Dr. ', d.first_name, ' ', d.last_name) AS doctor_name,
       COALESCE(SUM(a.status = 'Completed'), 0) AS completed_visits,
       COALESCE(SUM(a.status = 'Scheduled'), 0) AS upcoming_visits,
       COUNT(DISTINCT CASE WHEN a.status IN ('Scheduled','Completed') THEN a.patient_id END) AS patients
FROM doctors d LEFT JOIN appointments a ON a.doctor_id = d.doctor_id
GROUP BY d.doctor_id, d.first_name, d.last_name;

CREATE VIEW v_patient_visits AS
SELECT p.patient_id, CONCAT(p.first_name, ' ', p.last_name) AS patient_name,
       a.appointment_id, a.start_time,
       CONCAT(d.first_name, ' ', d.last_name) AS doctor_name,
       c.chief_complaint, c.diagnosis, a.status
FROM appointments a
JOIN patients p ON p.patient_id = a.patient_id
JOIN doctors  d ON d.doctor_id  = a.doctor_id
LEFT JOIN consultations c ON c.appointment_id = a.appointment_id;

CREATE VIEW v_ai_accuracy AS
SELECT m.name, m.version,
       COUNT(f.feedback_id) AS reviewed,
       ROUND(100 * SUM(f.was_correct) / NULLIF(COUNT(f.feedback_id), 0), 1) AS accuracy_pct
FROM ai_models m
JOIN symptom_checks sc ON sc.model_id = m.model_id
JOIN ai_predictions ap ON ap.check_id = sc.check_id
JOIN ai_feedback f     ON f.prediction_id = ap.prediction_id
GROUP BY m.model_id;

-- Kaggle: how often each symptom appears for each disease
CREATE VIEW v_kaggle_disease_profile AS
SELECT d.name AS disease, s.name AS symptom, ds.weight,
       ROUND(100 * COUNT(kc.case_id) / (SELECT COUNT(*) FROM kaggle_cases x WHERE x.disease_id = d.disease_id), 1) AS seen_in_pct
FROM disease_symptoms ds
JOIN diseases d ON d.disease_id = ds.disease_id
JOIN symptoms s ON s.symptom_id = ds.symptom_id
JOIN kaggle_cases kc ON kc.disease_id = d.disease_id
JOIN kaggle_case_symptoms kcs ON kcs.case_id = kc.case_id AND kcs.symptom_id = s.symptom_id
GROUP BY d.disease_id, d.name, s.symptom_id, s.name, ds.weight;

