-- =====================================================================
-- MORE SAMPLE DATA: extra patients, medicines, lab tests and a visit history
-- spread across the doctors (every date falls inside that doctor's schedule)
-- =====================================================================







-- appointments 6-13 are history, 14-15 are always the next free weekday of that doctor






-- =====================================================================
-- KAGGLE KNOWLEDGE BASE (symptoms, diseases, precautions, raw records)
-- =====================================================================
-- >>> KAGGLE DATA START
-- Generated by kaggle_import.py from data/kaggle/*.csv. Edit the CSVs and re-run the script, not this block.
-- Source: Kaggle, 'Disease Symptom Prediction' (itachi9604)
-- 4920 patient records | 41 diseases | 131 symptoms




-- Raw Kaggle records, one row per patient record


-- Build the AI knowledge base from the raw Kaggle records, inside MySQL:
--   weight = (records of the disease that show the symptom / all records of the disease)
--            * (0.5 + Kaggle severity / 14)        -> always between 0.01 and 1
SELECT kc.disease_id, kcs.symptom_id,
       GREATEST(0.01, ROUND(ROUND(COUNT(*) / t.n, 4) * (0.5 + ROUND(s.severity_weight / 14, 4)), 2))
FROM kaggle_case_symptoms kcs
JOIN kaggle_cases kc ON kc.case_id = kcs.case_id
JOIN symptoms s      ON s.symptom_id = kcs.symptom_id
JOIN (SELECT disease_id, COUNT(*) AS n FROM kaggle_cases GROUP BY disease_id) t ON t.disease_id = kc.disease_id
GROUP BY kc.disease_id, kcs.symptom_id, t.n, s.severity_weight;


-- <<< KAGGLE DATA END

-- =====================================================================
-- DEMO AI CHECK: Rohan's symptoms on 20 Oct, scored exactly like match_diseases()
-- =====================================================================
VALUES (1,1,1,'High fever since 2 days, cough, hard to breathe',1,'2026-10-20 08:30:00');

SELECT 1, symptom_id, sev, 2 FROM (
    SELECT 'high_fever' AS k, 4 AS sev UNION ALL SELECT 'cough', 4 UNION ALL SELECT 'breathlessness', 3 UNION ALL
    SELECT 'chills', 3 UNION ALL SELECT 'phlegm', 3 UNION ALL SELECT 'rusty_sputum', 3 UNION ALL SELECT 'chest_pain', 2) x
JOIN symptoms s ON s.kaggle_key = x.k;

SELECT 1, disease_id, score, ROW_NUMBER() OVER (ORDER BY score DESC, disease_id),
       CASE WHEN severity_level >= 4 THEN 'Urgent' WHEN severity_level = 3 THEN 'Soon' ELSE 'Routine' END
FROM (SELECT d.disease_id, d.severity_level,
             ROUND(SUM(ds.weight * i.severity)
                   / (SELECT SUM(w.weight * 5) FROM disease_symptoms w WHERE w.disease_id = d.disease_id)
                   * SUM(i.severity)
                   / (SELECT SUM(a.severity) FROM symptom_check_items a WHERE a.check_id = 1), 4) AS score
      FROM symptom_check_items i
      JOIN disease_symptoms ds ON ds.symptom_id = i.symptom_id
      JOIN diseases d ON d.disease_id = ds.disease_id
      WHERE i.check_id = 1
      GROUP BY d.disease_id, d.severity_level) m
ORDER BY score DESC, disease_id
LIMIT 5;

UPDATE consultations SET ai_check_id = 1 WHERE appointment_id = 1;

SELECT prediction_id, 3, disease_id = (SELECT disease_id FROM diseases WHERE name = 'Pneumonia'),
       (SELECT disease_id FROM diseases WHERE name = 'Pneumonia'), 'Matches clinical findings and chest exam'
FROM ai_predictions WHERE check_id = 1 AND prediction_rank = 1;

