INSERT INTO diseases (disease_id,name,icd10_code,severity_level,recommended_specialization_id,description) VALUES
 (1,'Fungal Infection','B49',1,6,'In humans, fungal infections occur when an invading fungus takes over an area of the body and is too much for the immune system to handle. Fungi can live in the air, soil, water, and plants. There are also some fungi that live naturally in the human body. Like many microbes, there are helpful fungi and harmful fungi.'),
 (2,'Allergy','T78.4',1,1,'An allergy is an immune system response to a foreign substance that''s not typically harmful to your body.They can include certain foods, pollen, or pet dander. Your immune system''s job is to keep you healthy by fighting harmful pathogens.'),
 (3,'GERD (Acid Reflux)','K21.9',2,7,'Gastroesophageal reflux disease, or GERD, is a digestive disorder that affects the lower esophageal sphincter (LES), the ring of muscle between the esophagus and stomach. Many people, including pregnant women, suffer from heartburn or acid indigestion caused by GERD.'),
 (4,'Chronic Cholestasis','K83.1',3,7,'Chronic cholestatic diseases, whether occurring in infancy, childhood or adulthood, are characterized by defective bile acid transport from the liver to the intestine, which is caused by primary damage to the biliary epithelium in most cases'),
 (5,'Drug Reaction','T88.7',3,1,'An adverse drug reaction (ADR) is an injury caused by taking medication. ADRs may occur following a single dose or prolonged administration of a drug or result from the combination of two or more drugs.'),
 (6,'Peptic Ulcer Disease','K27.9',3,7,'Peptic ulcer disease (PUD) is a break in the inner lining of the stomach, the first part of the small intestine, or sometimes the lower esophagus. An ulcer in the stomach is called a gastric ulcer, while one in the first part of the intestines is a duodenal ulcer.'),
 (7,'AIDS','B20',5,8,'Acquired immunodeficiency syndrome (AIDS) is a chronic, potentially life-threatening condition caused by the human immunodeficiency virus (HIV). By damaging your immune system, HIV interferes with your body''s ability to fight infection and disease.'),
 (8,'Diabetes','E11',3,4,'Diabetes is a disease that occurs when your blood glucose, also called blood sugar, is too high. Blood glucose is your main source of energy and comes from the food you eat. Insulin, a hormone made by the pancreas, helps glucose from food get into your cells to be used for energy.'),
 (9,'Gastroenteritis','A09',2,7,'Gastroenteritis is an inflammation of the digestive tract, particularly the stomach, and large and small intestines. Viral and bacterial gastroenteritis are intestinal infections associated with symptoms of diarrhea , abdominal cramps, nausea , and vomiting .'),
 (10,'Bronchial Asthma','J45',3,3,'Bronchial asthma is a medical condition which causes the airway path of the lungs to swell and narrow. Due to this swelling, the air path produces excess mucus making it hard to breathe, which results in coughing, short breath, and wheezing. The disease is chronic and interferes with daily working.'),
 (11,'Hypertension','I10',3,2,'Hypertension (HTN or HT), also known as high blood pressure (HBP), is a long-term medical condition in which the blood pressure in the arteries is persistently elevated. High blood pressure typically does not cause symptoms.'),
 (12,'Migraine','G43.9',2,5,'A migraine can cause severe throbbing pain or a pulsing sensation, usually on one side of the head. It''s often accompanied by nausea, vomiting, and extreme sensitivity to light and sound. Migraine attacks can last for hours to days, and the pain can be so severe that it interferes with your daily activities.'),
 (13,'Cervical Spondylosis','M47.812',2,9,'Cervical spondylosis is a general term for age-related wear and tear affecting the spinal disks in your neck. As the disks dehydrate and shrink, signs of osteoarthritis develop, including bony projections along the edges of bones (bone spurs).'),
 (14,'Paralysis (Brain Hemorrhage)','I61.9',5,5,'Intracerebral hemorrhage (ICH) is when blood suddenly bursts into brain tissue, causing damage to your brain. Symptoms usually appear suddenly during ICH. They include headache, weakness, confusion, and paralysis, particularly on one side of your body.'),
 (15,'Jaundice','R17',3,7,'Yellow staining of the skin and sclerae (the whites of the eyes) by abnormally high blood levels of the bile pigment bilirubin. The yellowing extends to other tissues and body fluids. Jaundice was once called the "morbus regius" (the regal disease) in the belief that only the touch of a king could cure it'),
 (16,'Malaria','B54',4,8,'An infectious disease caused by protozoan parasites from the Plasmodium family that can be transmitted by the bite of the Anopheles mosquito or by a contaminated needle or transfusion. Falciparum malaria is the most deadly type.'),
 (17,'Chickenpox','B01.9',2,8,'Chickenpox is a highly contagious disease caused by the varicella-zoster virus (VZV). It can cause an itchy, blister-like rash. The rash first appears on the chest, back, and face, and then spreads over the entire body, causing between 250 and 500 itchy blisters.'),
 (18,'Dengue','A90',4,8,'An acute infectious disease caused by a flavivirus (species Dengue virus of the genus Flavivirus), transmitted by aedes mosquitoes, and characterized by headache, severe joint pain, and a rash. — called also breakbone fever, dengue fever.'),
 (19,'Typhoid','A01.0',4,8,'An acute illness characterized by fever caused by infection with the bacterium Salmonella typhi. Typhoid fever has an insidious onset, with fever, headache, constipation, malaise, chills, and muscle pain. Diarrhea is uncommon, and vomiting is not usually severe.'),
 (20,'Hepatitis A','B15.9',3,7,'Hepatitis A is a highly contagious liver infection caused by the hepatitis A virus. The virus is one of several types of hepatitis viruses that cause inflammation and affect your liver''s ability to function.'),
 (21,'Hepatitis B','B16.9',4,7,'Hepatitis B is an infection of your liver. It can cause scarring of the organ, liver failure, and cancer. It can be fatal if it isn''t treated. It''s spread when people come in contact with the blood, open sores, or body fluids of someone who has the hepatitis B virus.'),
 (22,'Hepatitis C','B17.10',4,7,'Inflammation of the liver due to the hepatitis C virus (HCV), which is usually spread via blood transfusion (rare), hemodialysis, and needle sticks. The damage hepatitis C does to the liver can lead to cirrhosis and its complications as well as cancer.'),
 (23,'Hepatitis D','B17.0',4,7,'Hepatitis D, also known as the hepatitis delta virus, is an infection that causes the liver to become inflamed. This swelling can impair liver function and cause long-term liver problems, including liver scarring and cancer. The condition is caused by the hepatitis D virus (HDV).'),
 (24,'Hepatitis E','B17.2',3,7,'A rare form of liver inflammation caused by infection with the hepatitis E virus (HEV). It is transmitted via food or drink handled by an infected person or through infected water supplies in areas where fecal matter may get into the water. Hepatitis E does not cause chronic liver disease.'),
 (25,'Alcoholic Hepatitis','K70.10',4,7,'Alcoholic hepatitis is a diseased, inflammatory condition of the liver caused by heavy alcohol consumption over an extended period of time. It''s also aggravated by binge drinking and ongoing alcohol use. If you develop this condition, you must stop drinking alcohol'),
 (26,'Tuberculosis','A15.9',4,3,'Tuberculosis (TB) is an infectious disease usually caused by Mycobacterium tuberculosis (MTB) bacteria. Tuberculosis generally affects the lungs, but can also affect other parts of the body. Most infections show no symptoms, in which case it is known as latent tuberculosis.'),
 (27,'Common Cold','J00',1,1,'The common cold is a viral infection of your nose and throat (upper respiratory tract). It''s usually harmless, although it might not feel that way. Many types of viruses can cause a common cold.'),
 (28,'Pneumonia','J18.9',4,3,'Pneumonia is an infection in one or both lungs. Bacteria, viruses, and fungi cause it. The infection causes inflammation in the air sacs in your lungs, which are called alveoli. The alveoli fill with fluid or pus, making it difficult to breathe.'),
 (29,'Hemorrhoids (Piles)','K64.9',2,7,'Hemorrhoids, also spelled haemorrhoids, are vascular structures in the anal canal. In their ... Other names, Haemorrhoids, piles, hemorrhoidal disease .'),
 (30,'Heart Attack','I21.9',5,2,'The death of heart muscle due to the loss of blood supply. The loss of blood supply is usually caused by a complete blockage of a coronary artery, one of the arteries that supplies blood to the heart muscle.'),
 (31,'Varicose Veins','I83.90',2,2,'A vein that has enlarged and twisted, often appearing as a bulging, blue blood vessel that is clearly visible through the skin. Varicose veins are most common in older adults, particularly women, and occur especially on the legs.'),
 (32,'Hypothyroidism','E03.9',2,4,'Hypothyroidism, also called underactive thyroid or low thyroid, is a disorder of the endocrine system in which the thyroid gland does not produce enough thyroid hormone.'),
 (33,'Hyperthyroidism','E05.90',3,4,'Hyperthyroidism (overactive thyroid) occurs when your thyroid gland produces too much of the hormone thyroxine. Hyperthyroidism can accelerate your body''s metabolism, causing unintentional weight loss and a rapid or irregular heartbeat.'),
 (34,'Hypoglycemia','E16.2',4,4,'Hypoglycemia is a condition in which your blood sugar (glucose) level is lower than normal. Glucose is your body''s main energy source. Hypoglycemia is often related to diabetes treatment. But other drugs and a variety of conditions — many rare — can cause low blood sugar in people who don''t have diabetes.'),
 (35,'Osteoarthritis','M19.90',2,9,'Osteoarthritis is the most common form of arthritis, affecting millions of people worldwide. It occurs when the protective cartilage that cushions the ends of your bones wears down over time.'),
 (36,'Arthritis','M13.9',2,9,'Arthritis is the swelling and tenderness of one or more of your joints. The main symptoms of arthritis are joint pain and stiffness, which typically worsen with age. The most common types of arthritis are osteoarthritis and rheumatoid arthritis.'),
 (37,'Positional Vertigo (BPPV)','H81.10',2,5,'Benign paroxysmal positional vertigo (BPPV) is one of the most common causes of vertigo — the sudden sensation that you''re spinning or that the inside of your head is spinning. Benign paroxysmal positional vertigo causes brief episodes of mild to intense dizziness.'),
 (38,'Acne','L70.0',1,6,'Acne vulgaris is the formation of comedones, papules, pustules, nodules, and/or cysts as a result of obstruction and inflammation of pilosebaceous units (hair follicles and their accompanying sebaceous gland). Acne develops on the face and upper trunk. It most often affects adolescents.'),
 (39,'Urinary Tract Infection','N39.0',2,10,'Urinary tract infection: An infection of the kidney, ureter, bladder, or urethra. Abbreviated UTI. Not everyone with a UTI has symptoms, but common symptoms include a frequent urge to urinate and pain or burning when urinating.'),
 (40,'Psoriasis','L40.9',2,6,'Psoriasis is a common skin disorder that forms thick, red, bumpy patches covered with silvery scales. They can pop up anywhere, but most appear on the scalp, elbows, knees, and lower back. Psoriasis can''t be passed from person to person. It does sometimes happen in members of the same family.'),
 (41,'Impetigo','L01.00',2,6,'Impetigo (im-puh-TIE-go) is a common and highly contagious skin infection that mainly affects infants and children. Impetigo usually appears as red sores on the face, especially around a child''s nose and mouth, and on hands and feet. The sores burst and develop honey-colored crusts.');
